(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let book=window.BOOKS[L.lang]||window.BOOK,engine=ReliabilityEngine.create(book,{canonicalQuery:L.canonical});const main=$('#main');
const staticSelectors=['.brand','.edition','.sidebar nav[aria-label="Hauptnavigation"]','.nav-heading','.sidebar-footer','.topbar','#chat-panel','.chat-fab','.page-footer','.skip'];
const staticAttributes=$$('[aria-label]').filter(el=>!el.closest('.topbar')).map(el=>({el,label:el.getAttribute('aria-label')}));
const staticMarkup=staticSelectors.map(selector=>({selector,html:$(selector)?.innerHTML||''}));
let state={read:[],caseName:'',path:'supplier',step:0,checks:{},notes:{},profile:''},previousQuestion='',chatStarted=false;
try{state={...state,...JSON.parse(localStorage.getItem('reliability-workbook-v1')||'{}')};if(!Array.isArray(state.read))state.read=[];}catch{}
const groups=[['Grundlagen & Systemkontext',1,4],['Modellierung & Fehleranalyse',5,10],['Komponenten & Zulieferer',11,13],['Statistik & Systemnachweis',14,17],['Feld & Verbesserung',18,19],['Fallstudien',20,20]];
const chapter=n=>book.chapters.find(c=>c.id===`chapter_${n}`),chapterLink=(n,label)=>`<a href="#chapter_${n}" class="pill">${esc(label||'Kapitel '+n)}</a>`;
const stages=[{name:'Kontext klären',chapters:[1,3,4],short:'Funktion · Grenze · Nutzung'},{name:'System modellieren',chapters:[5,6,7],short:'Ketten · Architektur · Anforderungen'},{name:'Fehler analysieren',chapters:[8,9,10],short:'FMEA · Ursachen · Reserven'},{name:'Nachweis planen',chapters:[14,15],short:'Statistik · Stichprobe · Profil'},{name:'Komponente absichern',chapters:[11,12,13],short:'Evidenz · Grenzen · Version'},{name:'Integration prüfen',chapters:[16],short:'Zusammenspiel · Use Cases'},{name:'Entscheidung treffen',chapters:[17],short:'Freigabe · Bedingungen · Änderungen'},{name:'Lernen & verbessern',chapters:[18,19],short:'Feld · Ursachen · Wirksamkeit'}];
const paths={
 supplier:{title:'Zuliefernachweis bewerten',sub:'Passt die vorhandene Evidenz zu unserem Einsatz?',chapters:[11,12,14,15,16,17],steps:[
 ['Einsatz beschreiben','Ein Nachweis gilt für eine konkrete Ausführung und Anwendung. Beginne mit dem benötigten Einsatz, bevor du einen Prüfbericht bewertest.',[3,4,7,11],['Funktion und zulässige Degradation benannt','Einbau, Umgebung und Nutzungsprofil festgelegt','Ausführung, Hardware- und Firmwarestand erfasst']],
 ['Evidenz abgleichen','Prüfe die vorhandenen Nachweise gegen den tatsächlichen Einsatz. Ein anderes Labor allein begründet keine vollständige Wiederholung.',[11,12,14],['Berichtsmuster passt zum Lieferstand','Messort, Belastungsprofil und beobachtete Funktion passen','Musterrepräsentativität, Ausfälle und Zensierungen sind dokumentiert','Statistische Aussage und Modellannahmen sind nachvollziehbar']],
 ['Lücken schließen','Unterschiede werden technisch begründet. Wähle gezielte Ergänzungen für einen veränderten Mechanismus, eine neue Belastung oder eine fehlende Aussage.',[10,12,15,16],['Abweichungen und ihre Wirkung beschrieben','Zusätzlicher Nachweis hat klares Ziel und Akzeptanzkriterium','Integration prüft reale Einbaubedingungen und Übergaben']],
 ['Übernahme entscheiden','Halte fest, für welchen Einsatz und welche Version die Evidenz akzeptiert wird. Richte den Rückmeldeweg ein.',[11,17,18,19],['Akzeptiert, eingeschränkt akzeptiert oder weitere Evidenz nötig','Bedingungen und Verantwortliche festgehalten','Änderungsmitteilung und Feldmonitoring eingerichtet']]]},
 integration:{title:'Integration prüfen',sub:'Funktionieren die Teile im tatsächlichen Zusammenspiel?',chapters:[3,5,6,8,10,13,16,17],steps:[
 ['Grenze & Ketten','Definiere Beginn und Erfolgspunkt der Funktion. Das Ende kann am Gerät oder erst im bestätigten Untersuchungsablauf liegen.',[3,4,5,6],['Produkt- oder Ablaufgrenze festgelegt','Funktions- und Signalketten erfasst','Inputs, Outputs, Zustände, Feedback und gemeinsame Ressourcen benannt']],
 ['Risiken & Versionen','Die Übergabe braucht mehr als ein passendes Datenformat. Eine alte Bereitschaftsmeldung kann einen neuen Auftrag falsch freigeben.',[6,8,9,13],['Versionen und Schnittstellenverträge dokumentiert','Fehlende, falsche, verspätete, veraltete und doppelte Signale analysiert','Gemeinsame Ursachen und Rückfallebenen betrachtet']],
 ['Tests & Reserven','Prüfe den Normalfall, ungünstige zulässige Kombinationen und Wiederanlauf. Explorative Grenzsuche ist eine zusätzliche Aussage.',[10,13,16],['Erwartete Funktion und erlaubte Fehlerreaktion vorab definiert','Last, Versorgung, Timing und Nachrichten gezielt variiert','Reale Einbaubedingungen und physikalische Wirkungen abgesichert','Messbarer Abstand zu relevanten Grenzen und Unsicherheit dokumentiert']],
 ['Nachweis & Freigabe','Verknüpfe jede Anforderung mit passender Evidenz und benenne den Geltungsbereich.',[16,17,18],['Ergebnisse mit Konfiguration und Zuständen reproduzierbar','Rückkehr aus Störung und Rückfallebene geprüft','Nachweismatrix, Freigabebedingungen und offene Punkte dokumentiert']]]},
 statistics:{title:'Lebensdauer nachweisen',sub:'Welche Aussage soll der Versuch belegen?',chapters:[7,10,12,14,15],steps:[
 ['Ziel & Population','Erst die gewünschte Aussage, dann der Versuchsplan. Lege die Einheit der Nutzung fest: Stunden, Zyklen oder Kalenderzeit.',[4,7,14],['Funktion, Ausfallkriterium und Population beschrieben','Zielnutzung und Zuverlässigkeitsziel festgelegt','Konfidenzniveau und Richtung der Grenze vorab vereinbart']],
 ['Modell & Daten','Die Modellwahl folgt Daten, Mechanismus und Prüfart. Stundenaddition und binomialer Nachweis beruhen auf unterschiedlichen Annahmen.',[10,14,15],['Unabhängigkeit und Repräsentativität begründet','Verteilung beziehungsweise Rate passt zur Frage','Zensierungen, Abbrüche und Rohdaten werden erfasst']],
 ['Prüfplan festlegen','Plane Stichprobe, Prüfnutzung, akzeptierte Ausfälle und Chance auf einen bestandenen Nachweis zusammen. Ein kleines Budget verändert keine statistische Anforderung.',[12,15],['Annahmezahl und Entscheidung vor Testbeginn festgelegt','Nachweiserfolgswahrscheinlichkeit bewertet','Beschleunigung nur mit passendem validiertem Mechanismus','Funktionsbeobachtung während und nach Belastung geplant']],
 ['Aussage berichten','Berichte Schätzung, Unsicherheitsgrenze, Modell und Geltungsbereich gemeinsam.',[14,15,17],['Alle Einheiten einschließlich erfolgreicher und zensierter dokumentiert','Relevante Ausfälle technisch untersucht','Aussage auf geprüfte Nutzung und Population begrenzt']]]},
 fmea:{title:'FMEA vorbereiten',sub:'Von Inputs und Outputs zur Systemwirkung.',chapters:[3,5,6,8,9],steps:[
 ['System abgrenzen','Betrachte das System und seine Umgebung und wende die gleiche Sicht auf Subsysteme erneut an.',[3,4],['Systemgrenze und Bewertungsfunktion festgelegt','Inputs, Outputs, zusätzliche Einwirkungen und Rückwirkungen erfasst','Zustände und Nutzung ergänzt']],
 ['Ketten & Architektur','Zerlege entlang von Funktionen und Signalen und ordne die Umsetzung in Hardware und Software zu.',[5,6,7],['Funktions- und Signalketten mit Übergaben beschrieben','Architekturbezug und Anforderungen verknüpft','Annahmen und zugesicherte Leistungen der Schnittstellen dokumentiert']],
 ['Fehler & Wirkungen','Formuliere konkrete Abweichungen einschließlich Zeit und Kontext. Folge ihrer Wirkung über die Ebenen.',[8,9],['Lokale, nächsthöhere und Systemwirkung getrennt','Ursachen und vorhandene Kontrollen beschrieben','Fehlerkombinationen und gemeinsame Ursachen zusätzlich bewertet']],
 ['Maßnahmen & Rückmeldung','Eine Maßnahme endet mit einem Wirksamkeitsnachweis. Neue Befunde verändern die FMEA.',[8,16,19],['Verantwortliche, Termin und Prüfziel vereinbart','Wirksamkeit und Restzustand bewertet','Änderungen in Anforderungen, Modellen und Tests zurückgeführt']]]},
 field:{title:'Feldausfall untersuchen',sub:'Vom Ereignis zur nachgewiesenen Verbesserung.',chapters:[8,16,18,19,20],steps:[
 ['Ereignis sichern','Serviceaustausch, bestätigter Funktionsverlust und No Fault Found sind verschiedene Ereignisse.',[18,19],['Funktion, Zeitpunkt, Zustand und Konfiguration gesichert','Befund und seine Sicherheit dokumentiert','Mehrfachmeldungen desselben Ereignisses erkannt']],
 ['Nenner & Kohorten','Die bloße Ausfallzahl reicht nicht. Nutzung, Alter, Version und Meldeverfahren beeinflussen den Vergleich.',[14,18],['Passender Nenner und Beobachtungsdauer erfasst','Vergleichbare Kohorten gebildet','Zensierung und wiederkehrende Ereignisse passend behandelt','Unsicherheit und Datenqualität bewertet']],
 ['Ursache unterscheiden','Stelle konkurrierende Hypothesen auf und wähle Prüfungen, die sie voneinander trennen.',[8,10,16,19,20],['Symptom, Hypothese, Befund und Mechanismus getrennt','Auslösende Kombination reproduziert oder Unsicherheit dokumentiert','Komponente, Spezifikation und Integration offen geprüft']],
 ['Verbessern & lernen','Ein Neustart ist eine Wiederherstellung. Eine nachhaltige Verbesserung braucht eine wirksame Maßnahme und geeigneten Nachweis.',[17,18,19],['Wirkmechanismus der Maßnahme begründet','Reproduktions- und Regressionstest bestanden','Feldwirksamkeit mit passendem Vergleich bewertet','FMEA, Modelle, Supplier-Anforderungen und Prüfnachweise aktualisiert']]]},
 change:{title:'Änderung bewerten',sub:'Was berührt ein Update oder neuer Einsatz?',chapters:[6,11,13,16,17],steps:[
 ['Änderung erfassen','Der Name einer Änderung sagt wenig über ihre Wirkung. Eine neue Firmware kann auch die Hardwarebelastung verändern.',[6,13,17],['Alter und neuer Stand eindeutig dokumentiert','Betroffene Nutzung und Versionskombination beschrieben','Änderungsweg und Verantwortliche festgelegt']],
 ['Wirkung verfolgen','Verfolge Funktion, Architektur, Schnittstellen, Mechanismus und bestehende Evidenz.',[5,6,8,10,17],['Timing, Protokoll, Ressourcen und Leistungsaufnahme bewertet','Betroffene Anforderungen und Nachweise markiert','Unbetroffenheit erhaltener Evidenz begründet']],
 ['Gezielt prüfen','Ergänze betroffene Nachweise und führe gezielte Regression durch. Ein fremdes Update begründet nicht die Neuqualifikation aller Komponenten.',[11,13,16,17],['Kompatibilität betroffener Kombinationen nachgewiesen','Neue thermische oder mechanische Wirkung passend geprüft','Rückfallebenen und Wiederanlauf berücksichtigt']],
 ['Gültigkeit entscheiden','Offene Kombinationen werden nicht als freigegeben behandelt. Feldbeobachtung allein ersetzt die Entscheidung nicht.',[6,17,18],['Unverändert gültig, unter Bedingungen gültig oder zusätzliche Evidenz nötig','Freigabestatus, Einschränkungen und Nachweise aktualisiert','Monitoring und Folgeschritte festgelegt']]]}
};
function save(){try{localStorage.setItem('reliability-workbook-v1',JSON.stringify(state));}catch{toast('Speichern im Browser ist blockiert. Du kannst deine Mappe exportieren.');}updateProgress();}
function toast(s){$('#toast').textContent=L.tr(s);$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,3200);}
function updateProgress(){const n=state.read.filter(x=>chapter(x)).length;$('#progress-label').textContent=L.tr(`${n} von 20 Kapiteln gelesen`);$('#progress-bar').style.width=`${n*5}%`;$$('.chapter-link').forEach(a=>a.classList.toggle('read',state.read.includes(Number(a.dataset.chapter))));}
function nav(){let out='';for(const [label,a,b]of groups){out+=`<div class="chapter-group">${label}</div>`;for(let n=a;n<=b;n++)out+=`<a href="#chapter_${n}" data-chapter="${n}" class="chapter-link"><span>${String(n).padStart(2,'0')}</span><span>${esc(chapter(n).title.replace(/^\d+ /,''))}</span></a>`;}out+='<div class="chapter-group">Zum Nachschlagen</div>';for(const c of book.chapters.slice(20))out+=`<a href="#${c.id}" class="chapter-link"><span>↳</span><span>${esc(c.title)}</span></a>`;$('#chapters').innerHTML=L.html(out);updateProgress();}
function home(){const topics=[['supplier','◇'],['integration','⇄'],['statistics','∿']];return`<span class="eyebrow">ZUVERLÄSSIGKEIT VON RÖNTGENSYSTEMEN</span><section class="hero"><div><span class="eyebrow">WISSEN, DAS IN DER PRAXIS HILFT</span><h1>Von der Frage zum<br>belastbaren Nachweis.</h1><p>Verstehe Zuverlässigkeit. Wähle die passende Methode. Und verbinde Komponenten, Integration und Felderfahrung zu einem nachvollziehbaren Ergebnis.</p><div class="hero-actions"><a class="btn primary" href="#navigator">Aufgabe bearbeiten <span>↗</span></a><a class="btn" href="#chapter_1">Mit den Grundlagen beginnen</a></div></div><div class="hero-art" aria-label="Lernweg: Verstehen, Nachweisen, Verbessern"><div class="art-circle"></div><div class="art-node"><b>01</b> Verstehen & zerlegen</div><div class="art-line"></div><div class="art-node"><b>02</b> Analysieren & nachweisen</div><div class="art-line"></div><div class="art-node"><b>03</b> Beobachten & verbessern</div></div></section><div class="stats"><span><strong>20</strong>Kapitel</span><span><strong>10</strong>Schaubilder</span><span><strong>235</strong>Abschnitte</span><span><strong>6</strong>Arbeitswege</span></div><div class="section-heading"><h2>Woran arbeitest du gerade?</h2><a class="muted" href="#navigator">Alle Arbeitswege ↗</a></div><div class="cards">${topics.map(([id,icon])=>`<a class="card" href="#navigator/${id}"><span class="card-icon">${icon}</span><h3>${paths[id].title}</h3><p>${paths[id].sub}</p><span class="arrow">Schritt für Schritt starten →</span></a>`).join('')}</div><div class="section-heading"><h2>Der rote Faden</h2><span class="muted">Ein Lebenszyklus. Verbundene Nachweise.</span></div><div class="process-grid">${stages.map((s,i)=>`<a class="process-card" href="#chapter_${s.chapters[0]}"><span>STATION ${String(i+1).padStart(2,'0')}</span><strong>${s.name}</strong><small>${s.short}</small></a>`).join('')}</div><div class="note">Neue Erkenntnisse aus dem Feld führen zurück in Anforderungen, Modelle und Prüfungen. Die interaktiven Arbeitswege und Schaubilder helfen dir, den passenden Einstieg zu finden.</div><div class="section-heading"><h2>Einfach fragen, gezielt weiterlesen.</h2></div><div class="tag-list">${['Was unterscheidet Qualität und Zuverlässigkeit?','Wie bereite ich eine FMEA vor?','Was bedeutet Konfidenzniveau?','Wie werte ich Feldausfälle aus?'].map(q=>`<button data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div>`;}
function blockHtml(b){switch(b.type){case'paragraph':return`<p ${b.anchor?'id="'+esc(b.anchor)+'"':''}>${b.html}</p>`;case'caption':return`<p class="caption">${b.html}</p>`;case'item':return`<li>${b.html}</li>`;case'math':return`<div class="math-wrap">${b.html}</div>`;case'image':return`<figure class="book-figure"><button class="figure-open" data-image="${esc(b.src)}" data-caption="${esc(b.alt)}" aria-label="${esc(b.alt)} ${esc(L.tr('vergrößern'))}"><img src="${esc(b.src)}" alt="${esc(b.alt)}" loading="lazy"></button><figcaption>${esc(L.tr('Zum Vergrößern anklicken'))}</figcaption>${figureLabels(b.src)}</figure>`;case'table':return`<div class="table-wrap"><table><thead><tr>${b.rows[0].map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${b.rows.slice(1).map(row=>`<tr>${row.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;default:return'';}}
function blocksHtml(blocks){let out='',list=false;for(const b of blocks){if(b.type==='item'&&!list){out+='<ul>';list=true;}if(b.type!=='item'&&list){out+='</ul>';list=false;}out+=blockHtml(b);}if(list)out+='</ul>';return out;}
function answersFor(n,deep){const prefix=deep?'Zur Vertiefungsübung in Kapitel '+n+':':'Zu Kapitel '+n+':';const original=window.BOOKS.de.chapters.find(c=>c.id==='appendix_A'),translated=book.chapters.find(c=>c.id==='appendix_A');return original.sections.flatMap((s,si)=>s.blocks.map((b,bi)=>b.text?.startsWith(prefix)?blockHtml(translated.sections[si].blocks[bi]):'')).join('');}
function reader(id,focus){const c=book.chapters.find(c=>c.id===id);if(!c)return empty('Diese Stelle gibt es nicht.','Über die Navigation findest du alle Kapitel und Anhänge.');const n=Number(id.replace('chapter_','')),isChapter=!!chapter(n);let start=isChapter?`<span class="eyebrow">KAPITEL ${String(n).padStart(2,'0')} / 20</span>`:'<span class="eyebrow">ZUM NACHSCHLAGEN</span>';
return`<div class="breadcrumb"><a href="#home">Übersicht</a> / ${isChapter?'Handbuch':'Nachschlagen'}</div><div class="page-title">${start}<h1>${esc(c.title.replace(/^\d+ /,''))}</h1></div><div class="reader-layout"><article class="reader">${c.sections.map((s,i)=>{const originalTitle=window.BOOKS.de.chapters.find(x=>x.id===c.id).sections[i].title,ex=/^(Übung|Vertiefungsübung)$/.test(originalTitle),ans=isChapter&&ex?answersFor(n,originalTitle==='Vertiefungsübung'):'';return`<section class="reader-section ${ex?'exercise':''}" id="section-${i}">${window.BOOKS.de.chapters.find(x=>x.id===c.id).sections[i].title==='Einführung'?'':`<h2>${esc(s.title)}</h2>`}${blocksHtml(s.blocks)}${ans?`<details><summary>${esc(L.tr('Musterantwort ansehen'))}</summary>${ans}</details>`:''}</section>`;}).join('')}${isChapter?`<div class="chapter-actions">${n>1?`<a class="btn" href="#chapter_${n-1}">← Voriges Kapitel</a>`:'<a class="btn" href="#home">← Übersicht</a>'}${n<20?`<a class="btn primary" href="#chapter_${n+1}">Nächstes Kapitel →</a>`:'<a class="btn primary" href="#navigator">Jetzt anwenden →</a>'}</div>`:''}</article><aside class="reader-toc" aria-label="Abschnitte"><strong>IN DIESEM KAPITEL</strong>${c.sections.map((s,i)=>`<a href="#${id}/section-${i}">${esc(s.title)}</a>`).join('')}${isChapter?`<button class="btn ${state.read.includes(n)?'primary':''}" id="mark-read" data-number="${n}">${state.read.includes(n)?'✓ Als gelesen markiert':'Als gelesen markieren'}</button>`:''}<button class="btn" data-question="${esc('Erkläre '+c.title.replace(/^\d+ /,''))}">✦ Assistent fragen</button><a class="btn" href="#navigator">Im Arbeitsweg anwenden ↗</a></aside></div>`;}
function figureLabels(src){if(L.lang==='de')return '';const key=book.figures.find(f=>f.src===src)?.key;const rows=window.FIGURE_LABELS?.[key]||[];return '<details class="figure-labels"><summary>'+esc(L.tr('Beschriftungen'))+'</summary><dl>'+rows.map(r=>'<dt>'+esc(r[0])+'</dt><dd>'+esc(r[L.lang==='zh'?2:1])+'</dd>').join('')+'</dl></details>';}
function figures(){return`<div class="page-title"><span class="eyebrow">VISUELLE ORIENTIERUNG</span><h1>Das Ganze im Blick.</h1><p>Vom Lebenszyklus bis zum Ereignistrend. Öffne ein Schaubild in voller Größe oder springe direkt zum zugehörigen Kapitel.</p>${L.lang!=='de'?'<p class="lang-note">'+esc(L.tr('Grafiken sind Originalabbildungen. Die übersetzten Beschriftungen findest du darunter.'))+'</p>':''}</div><div class="figure-grid">${book.figures.slice().sort((a,b)=>a.caption.localeCompare(b.caption)).map(f=>`<article class="figure-card" id="diagram_${esc(f.key)}"><button class="figure-open" data-image="${esc(f.src)}" data-caption="${esc(f.caption)}" aria-label="${esc(f.context)} vergrößern"><img src="${f.src}" alt="${esc(f.caption)}" loading="lazy"></button>${figureLabels(f.src)}<div class="figure-info"><h3>${esc(f.caption.split('  ')[0])}</h3><p>${esc(f.context)}</p><a href="#${f.chapter}">Im Zusammenhang lesen →</a></div></article>`).join('')}</div>`;}
function navigator(path,step){if(paths[path])state.path=path;if(Number.isInteger(step))state.step=step;const p=paths[state.path]||paths.supplier;state.step=Math.min(Math.max(state.step,0),p.steps.length-1);const [title,desc,refs,checks]=p.steps[state.step],key=state.path+'-'+state.step;const done=(i)=>{const k=state.path+'-'+i;return p.steps[i][3].every((_,j)=>state.checks[k+'-'+j]);};
return`<div class="page-title"><span class="eyebrow">METHODENNAVIGATOR</span><h1>Eine Frage. Ein klarer Arbeitsweg.</h1><p>Wähle deine Aufgabe. Die Schritte verbinden Methodenauswahl, passende Kapitel und deine eigene Dokumentation.</p></div><div class="path-choices">${Object.entries(paths).map(([id,x])=>`<button class="path-choice" aria-pressed="${state.path===id}" data-path="${id}"><strong>${esc(x.title)}</strong><span>${esc(x.sub)}</span></button>`).join('')}</div><div class="field"><label for="case-name">Deine Bewertungsaufgabe</label><input id="case-name" maxlength="180" value="${esc(state.caseName)}" placeholder="Zum Beispiel: Detektor in neuem Einbau qualifizieren"></div><div class="work-area"><nav class="steps" aria-label="Arbeitsschritte">${p.steps.map((s,i)=>`<button class="step ${i===state.step?'active':''} ${done(i)?'complete':''}" data-step="${i}" ${i===state.step?'aria-current="step"':''}><b>${done(i)?'✓':i+1}</b>${esc(s[0])}</button>`).join('')}</nav><section class="step-content"><span class="eyebrow">SCHRITT ${state.step+1} VON ${p.steps.length}</span><h2>${esc(title)}</h2><p>${esc(desc)}</p><div class="chapter-pills">${refs.map(n=>chapterLink(n)).join('')}</div><div>${checks.map((c,j)=>`<label class="check-row"><input type="checkbox" data-check="${key}-${j}" ${state.checks[key+'-'+j]?'checked':''}><span>${esc(c)}</span></label>`).join('')}</div><div class="field"><label for="step-notes">Notizen, Befund und noch offene Fragen</label><textarea id="step-notes" maxlength="12000" data-key="${key}" placeholder="Was wissen wir? Welche Evidenz fehlt? Was ist der nächste konkrete Schritt?">${esc(state.notes[key]||'')}</textarea></div><div class="work-controls"><button class="btn" data-export="markdown">Arbeitsmappe exportieren ↓</button>${state.step<p.steps.length-1?`<button class="btn primary" data-step="${state.step+1}">Nächster Schritt →</button>`:'<a class="btn primary" href="#tools">Meine Mappe ansehen →</a>'}</div><div class="note">Häkchen dokumentieren deinen Arbeitsstand und sind keine technische Freigabe. Notizen und Fortschritt werden lokal in diesem Browser gespeichert. Für die Weitergabe exportiere deine Mappe.</div></section></div>`;}
function empty(title,desc){return`<div class="empty"><h2>${esc(title)}</h2><p>${esc(desc)}</p><a class="btn" href="#home">Zur Übersicht</a></div>`;}
function searchPage(q){const results=engine.search(q,18);return`<div class="page-title"><span class="eyebrow">HANDBUCHSUCHE</span><h1>Passende Stellen zu deiner Frage.</h1><p data-user-text>${esc(q)}</p></div><div class="search-summary">${results.length?'Die '+results.length+' passendsten Abschnitte':'Keine passenden Abschnitte gefunden'} · <button class="btn" data-question="${esc(q)}">✦ Assistent fragen</button></div>${results.length?results.map(r=>`<article class="result"><small>${esc(r.chapterTitle)}</small><p><a href="#${r.chapter}/section-${r.section}">${esc(r.title)}</a></p><p>${esc(snippet(r.text,q))}</p></article>`).join(''):empty('Noch keine Fundstelle.','Versuche einen technischen Begriff wie FMEA, Feuchte, Zuverlässigkeit, Integration oder Konfidenzniveau.')}`;}
function snippet(text,q){const w=ReliabilityEngine.words(q),t=ReliabilityEngine.norm(text);let start=0;for(const x of w){const p=t.indexOf(x);if(p>=0){start=Math.max(0,p-75);break;}}return(start?'… ':'')+text.slice(start,start+310).replace(/\n/g,' ')+(text.length>start+310?' …':'');}
function tools(){const checks=Object.values(state.checks).filter(Boolean).length;return`<div class="page-title"><span class="eyebrow">DEINE WERKSTATT</span><h1>Wissen in Arbeit übersetzen.</h1><p>Dein Fortschritt, deine Arbeitsnotizen und ein kleiner Rechner für den binomialen Nullausfallnachweis.</p></div><div class="tools-grid"><section class="tool-box"><h2>Meine Arbeitsmappe</h2><p data-user-text>${state.caseName?esc(state.caseName):esc(L.tr('Noch keine Bewertungsaufgabe benannt.'))}</p><div class="big-result">${state.read.length}<small> / 20 Kapitel gelesen</small></div><p>${checks} erledigte Prüfpunkte · ${Object.values(state.notes).filter(Boolean).length} Notizfelder ausgefüllt</p><div class="hero-actions"><a class="btn primary" href="#navigator/${state.path}/${state.step}">Weiterarbeiten →</a><button class="btn" data-export="markdown">Mappe herunterladen ↓</button><button class="btn" data-export="json">Sicherung exportieren</button><button class="btn" id="import-button">Sicherung importieren</button><input type="file" id="import-file" accept="application/json,.json" hidden></div><p class="result-note">Die Mappe wird in deinem Browser gespeichert. Jeder Besucher hat seinen eigenen Arbeitsstand. Die Sicherung überträgt ihn auf einen anderen Browser.</p></section><section class="tool-box"><h2>Nullausfall-Stichprobe</h2><p>Jede unabhängige repräsentative Einheit absolviert die vollständige Zielnutzung. Keine Ausfälle werden akzeptiert.</p><form id="calc-form"><div class="field"><label for="target-r">Geforderte Zuverlässigkeit R₀ in Prozent</label><input id="target-r" type="number" min="0.01" max="99.9999" step="any" value="90" required></div><div class="field"><label for="target-c">Einseitiges Konfidenzniveau in Prozent</label><input id="target-c" type="number" min="0.01" max="99.9999" step="any" value="95" required></div><button class="btn primary" type="submit" style="margin-top:15px">Musterzahl berechnen →</button></form><div id="calc-result" aria-live="polite"></div><p class="result-note">n ≥ ln(1 − C) / ln(R₀), aufgerundet. Der Rechner ersetzt keine Prüfung von Unabhängigkeit, Repräsentativität, Nutzungsprofil und Mechanismus.</p>${chapterLink(15,'Grundlage in Kapitel 15')}</section></div><div class="note">Schulungs- und Arbeitshilfe: Die Beispiele sind Lehrfälle. Projektziele, Schutzgrenzen und Freigaben folgen den tatsächlich gültigen Anforderungen und Unternehmensprozessen.</div>`;}
function calc(){const r=Number($('#target-r').value)/100,c=Number($('#target-c').value)/100;if(!(r>0&&r<1&&c>0&&c<1)){$('#calc-result').innerHTML=L.html('<p>Bitte gib beide Werte strikt zwischen 0 und 100 Prozent ein.</p>');return;}const n=Math.ceil(Math.log1p(-c)/Math.log(r)),lower=Math.exp(Math.log1p(-c)/n);$('#calc-result').innerHTML=L.html(`<div class="big-result">${n.toLocaleString(L.locale)} <small>Einheiten</small></div><p class="result-note">Benötigt werden ${n.toLocaleString(L.locale)} vollständige unabhängige Erfolge ohne Ausfall. Die einseitige untere Grenze beträgt dann ${(lower*100).toLocaleString(L.locale,{maximumFractionDigits:4})} Prozent.</p>`);}
function route(){let parts;try{parts=decodeURIComponent(location.hash.slice(1)||'home').split('/');}catch{parts=['home'];}const [id,arg,s]=parts;document.title=id.startsWith('chapter_')?`${chapter(Number(id.slice(8)))?.title||'Kapitel'} · Reliability`:L.tr('Reliability · Handbuch & Werkstatt');if(id==='home')main.innerHTML=L.html(home());else if(id==='navigator')main.innerHTML=L.html(navigator(arg,s!==undefined?parseInt(s,10):undefined));else if(id==='figures')main.innerHTML=L.html(figures());else if(id==='tools'){main.innerHTML=L.html(tools());calc();}else if(id==='search'){const q=parts.slice(1).join('/');$('#search-input').value=q;main.innerHTML=L.html(searchPage(q));}else if(book.chapters.some(c=>c.id===id))main.innerHTML=L.html(reader(id,arg));else main.innerHTML=L.html(empty('Dieser Link ist nicht gültig.','Wähle eine Aufgabe oder ein Kapitel aus der Navigation.'));$$('.navlink').forEach(a=>a.classList.toggle('active',a.dataset.view===id));$$('.chapter-link').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+id));$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');updateProgress();if(arg?.startsWith('section-')||arg?.startsWith('source_')||arg?.startsWith('diagram_'))requestAnimationFrame(()=>document.getElementById(arg)?.scrollIntoView());else window.scrollTo({top:0});}
function openChat(){const p=$('#chat-panel');p.hidden=false;if(!chatStarted){message('assistant','Hallo! Beschreibe dein Thema oder deine Bewertungsfrage. Ich gebe dir eine handbuchbasierte Einordnung und verweise auf passende Kapitel. Ich nutze feste Fachantworten und Textstellen aus dieser Fassung; ich bin kein allgemeines KI-Modell.');chatStarted=true;}$('#chat-input').focus();}
function message(role,text,answer){const d=document.createElement('div');d.className='message '+(role==='user'?'user':'assistant');if(role==='user'||!answer)d.textContent=role==='user'?text:L.tr(text);else{d.innerHTML=L.html(`<small>${answer.kind==='passage'?'GEFUNDENE HANDBUCHSTELLE':answer.kind==='unknown'?'GRENZE DER HANDBUCHGRUNDLAGE':'EINORDNUNG AUS DEM HANDBUCH'}</small><p>${esc(L.tr(text))}</p>${answer.quote?`<blockquote>${esc(answer.quote)}</blockquote>`:''}${answer.refs?.length?`<div>${answer.refs.map(n=>`<a href="#chapter_${n}">Kapitel ${n} ↗</a>`).join('')}</div>`:''}${answer.kind==='passage'&&answer.passages?.length?`<a href="#${answer.passages[0].chapter}/section-${answer.passages[0].section}">Zur konkreten Fundstelle →</a>`:''}`); }$('#chat-messages').append(d);$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;}
function ask(q){if(!q.trim())return;openChat();message('user',q);const result=engine.answer(q,previousQuestion);previousQuestion=q;message('assistant',result.text,result);$('#chat-input').value='';}
function exportMap(format){let text,name,type;if(format==='json'){text=JSON.stringify({format:'reliability-workbook-v1',version:1,state},null,2);name='Reliability-Arbeitsmappe.json';type='application/json';}else{text='# '+L.tr('Reliability · Arbeitsmappe')+'\n\n'+L.tr('Aufgabe:')+' '+(state.caseName||L.tr('Noch nicht benannt'))+'\n'+L.tr('Grundlage:')+' ChatGPT XYZ3 V03\n'+L.tr('Export:')+' '+new Date().toLocaleString(L.locale)+'\n\n';for(const [id,p]of Object.entries(paths)){text+='## '+L.tr(p.title)+'\n\n';p.steps.forEach((s,i)=>{const key=id+'-'+i;text+='### '+(i+1)+' '+L.tr(s[0])+'\n\n';s[3].forEach((c,j)=>text+='- ['+(state.checks[key+'-'+j]?'x':' ')+'] '+L.tr(c)+'\n');text+='\n'+L.tr('Notizen:')+' '+(state.notes[key]||'—')+'\n\n'+L.tr('Passende Kapitel:')+' '+s[2].join(', ')+'\n\n';});}text+=L.tr('Gelesene Kapitel:')+' '+(state.read.join(', ')||'—')+'\n\n'+L.tr('Die Mappe ist Arbeitsdokumentation, keine technische Freigabe.')+'\n';name='Reliability-Arbeitsmappe.md';type='text/markdown';}const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Arbeitsmappe exportiert.');}
function importState(value){if(value?.format!=='reliability-workbook-v1'||value.version!==1||!value.state||typeof value.state!=='object')throw Error('Diese Datei ist keine gültige Reliability-Sicherung.');const src=value.state,next={...state,read:[],checks:{},notes:{}};if(Array.isArray(src.read))next.read=[...new Set(src.read.filter(n=>Number.isInteger(n)&&n>=1&&n<=20))];if(typeof src.caseName==='string')next.caseName=src.caseName.slice(0,180);if(paths[src.path])next.path=src.path;if(Number.isInteger(src.step)&&src.step>=0&&src.step<4)next.step=src.step;for(const id of Object.keys(paths))paths[id].steps.forEach((s,i)=>{const k=id+'-'+i;for(let j=0;j<s[3].length;j++)if(src.checks?.[k+'-'+j]===true)next.checks[k+'-'+j]=true;if(typeof src.notes?.[k]==='string')next.notes[k]=src.notes[k].slice(0,12000);});state=next;save();route();toast('Arbeitsmappe importiert.');}
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.dataset.language){setLanguage(t.dataset.language);return;}if(t.hasAttribute('data-chat-open'))openChat();if(t.dataset.question)ask(t.dataset.question);if(t.id==='chat-close'){$('#chat-panel').hidden=true;$('.chat-fab').focus();}if(t.id==='menu-toggle'){const open=$('#sidebar').classList.toggle('open');t.setAttribute('aria-expanded',open);}if(t.dataset.path){state.path=t.dataset.path;state.step=0;save();location.hash='navigator/'+state.path+'/0';}if(t.dataset.step!==undefined){state.step=Number(t.dataset.step);save();location.hash='navigator/'+state.path+'/'+state.step;}if(t.id==='mark-read'){const n=Number(t.dataset.number);state.read=state.read.includes(n)?state.read.filter(x=>x!==n):[...state.read,n];save();t.textContent=L.tr(state.read.includes(n)?'✓ Als gelesen markiert':'Als gelesen markieren');t.classList.toggle('primary',state.read.includes(n));}if(t.dataset.image){$('#modal-image').src=t.dataset.image;$('#modal-image').alt=t.dataset.caption;$('#modal-caption').textContent=t.dataset.caption;if($('#modal-labels'))$('#modal-labels').innerHTML=figureLabels(t.dataset.image);$('#figure-modal').showModal();}if(t.classList.contains('modal-close'))$('#figure-modal').close();if(t.dataset.export)exportMap(t.dataset.export);if(t.id==='import-button')$('#import-file').click();if(t.getAttribute('href')?.startsWith('#')&&t.closest('.chat-messages'))$('#chat-panel').hidden=true;});
document.addEventListener('input',e=>{if(e.target.id==='case-name'){state.caseName=e.target.value;save();}if(e.target.id==='step-notes'){state.notes[e.target.dataset.key]=e.target.value;save();}});
document.addEventListener('change',e=>{if(e.target.dataset.check){state.checks[e.target.dataset.check]=e.target.checked;save();const y=window.scrollY;main.innerHTML=L.html(navigator());window.scrollTo({top:y});}if(e.target.id==='import-file'){const f=e.target.files?.[0];if(!f)return;if(f.size>2e6){toast('Die Sicherung ist zu groß.');return;}f.text().then(t=>{try{importState(JSON.parse(t));}catch(err){toast(err.message);}});}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='search-form'){const q=$('#search-input').value.trim();if(q)location.hash='search/'+encodeURIComponent(q);}if(e.target.id==='chat-form')ask($('#chat-input').value.trim());if(e.target.id==='calc-form')calc();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#chat-panel').hidden=true;$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#search-input').focus();}});
function setLanguage(next){if(!L.set(next))return;const searchValue=$('#search-input').value;book=window.BOOKS[next]||window.BOOKS.de;engine=ReliabilityEngine.create(book,{canonicalQuery:L.canonical});for(const item of staticMarkup){const el=$(item.selector);if(el)el.innerHTML=L.html(item.html);}for(const item of staticAttributes)item.el.setAttribute('aria-label',L.tr(item.label));if(document.documentElement)document.documentElement.lang=L.locale;$$('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===next)));$('#search-input').value=searchValue;previousQuestion='';chatStarted=false;nav();route();try{if(window.history?.replaceState&&location.href){const url=new URL(location.href);if(next==='de')url.searchParams.delete('lang');else url.searchParams.set('lang',next);window.history.replaceState(null,'',url);}}catch{}}
window.addEventListener('hashchange',route);setLanguage(L.lang);
})();
